const ACCOUNT = 'dropratetcg@gmail.com';
const FOLDER = '1NhFIsWesgxlf059UMdx65ps9kFMqQeO9';
const FOLDER_NAME = 'Drop Rate - Pricing History Archives';
const KINDS = ['REFERENCE_HISTORY','OPENLIBRARY_REVIEWED'];
const SHA = /^[a-f0-9]{64}$/;
const FILE_ID = /^[A-Za-z0-9_-]{10,200}$/;
const MAX_OBJECT = 16000000;
function need(ok, code) { if (!ok) throw new Error(code); }
function copy(value) { return JSON.parse(JSON.stringify(value)); }
function exactKeys(value, keys) { return value && typeof value==='object' && !Array.isArray(value) && Object.keys(value).length===keys.length && keys.every(key=>Object.hasOwn(value,key)); }
function output(ctx, binary) { const item = {json:{ctx}}; if (binary && Object.keys(binary).length) item.binary=binary; return [item]; }
function currentArchive(ctx) { const p=ctx.checkpoint.page; need(p && p.archive_index < p.archives.length,'archive_state_invalid'); return p.archives[p.archive_index]; }
function currentMember(ctx) { const a=currentArchive(ctx); const i=ctx.checkpoint.page.object_index; need(i<a.objects.length,'member_state_invalid'); return a.objects[i]; }
function validCursor(value) { return value===null || (typeof value==='string' && /^[A-Za-z0-9_.:-]{1,1500}$/.test(value)); }
function validateArchive(a, kind) {
  need(exactKeys(a,['kind','manifest_sha256','archive_id','copy_status','last_recorded_verification_at','objects']),'archive_schema_invalid');
  need(a && a.kind===kind && SHA.test(a.manifest_sha256) && typeof a.archive_id==='string' && a.archive_id.length<=200,'archive_identity_invalid');
  need(['PENDING','RECORDED_BYTES_VERIFIED'].includes(a.copy_status) && Array.isArray(a.objects) && a.objects.length>=2 && a.objects.length<=16,'archive_members_invalid');
  const hashes=new Set();
  for (const m of a.objects) {
    need(exactKeys(m,['sha256','size_bytes','file_name','mime_type','role']),'archive_member_schema_invalid');
    need(m && SHA.test(m.sha256) && !hashes.has(m.sha256) && Number.isSafeInteger(m.size_bytes) && m.size_bytes>0 && m.size_bytes<=MAX_OBJECT,'archive_member_invalid');
    hashes.add(m.sha256);
    need(['application/gzip','application/json'].includes(m.mime_type) && typeof m.role==='string' && m.role.length<=100,'archive_member_type_invalid');
    need(typeof m.file_name==='string' && m.file_name.startsWith('drop-rate-'+kind.toLowerCase()+'-'+m.sha256+'.') && /^[a-z0-9_.-]{1,200}$/.test(m.file_name),'archive_member_name_invalid');
  }
  need(hashes.has(a.manifest_sha256),'archive_manifest_member_missing');
}
function emptyCheckpoint() { return {version:1,kind_index:0,cursors:[null,null],page:null,blocked_count:0,blocked_sample:[]}; }
function validateCheckpoint(c) {
  need(exactKeys(c,['version','kind_index','cursors','page','blocked_count','blocked_sample']),'checkpoint_schema_invalid');
  need(c && c.version===1 && Number.isInteger(c.kind_index) && c.kind_index>=0 && c.kind_index<=2,'checkpoint_invalid');
  need(Array.isArray(c.cursors) && c.cursors.length===2 && c.cursors.every(validCursor),'checkpoint_cursor_invalid');
  need(Number.isSafeInteger(c.blocked_count) && c.blocked_count>=0 && Array.isArray(c.blocked_sample) && c.blocked_sample.length<=20,'checkpoint_blocked_invalid');
  for(const issue of c.blocked_sample) {
    need(exactKeys(issue,['kind','manifest_sha256','reason']) || exactKeys(issue,['kind','manifest_sha256','reason','declared_size_bytes','maximum_object_bytes']),'checkpoint_issue_schema_invalid');
    need(KINDS.includes(issue.kind) && SHA.test(issue.manifest_sha256) && /^[A-Z0-9_]{1,120}$/.test(issue.reason),'checkpoint_issue_invalid');
    if(Object.hasOwn(issue,'declared_size_bytes')) need(Number.isSafeInteger(issue.declared_size_bytes) && issue.declared_size_bytes>0 && issue.maximum_object_bytes===MAX_OBJECT,'checkpoint_issue_size_invalid');
  }
  if (c.page!==null) {
    const p=c.page;
    need(exactKeys(p,['kind','archives','archive_index','object_index','has_more','next_cursor']),'checkpoint_page_schema_invalid');
    need(c.kind_index<2 && p.kind===KINDS[c.kind_index] && Array.isArray(p.archives) && p.archives.length<=2 && typeof p.has_more==='boolean' && validCursor(p.next_cursor),'checkpoint_page_invalid');
    need(!p.has_more || (p.next_cursor!==null && p.next_cursor!==c.cursors[c.kind_index]),'checkpoint_progress_invalid');
    need(p.has_more || p.next_cursor===null,'checkpoint_end_invalid');
    p.archives.forEach(a=>validateArchive(a,p.kind));
    need(Number.isInteger(p.archive_index) && p.archive_index>=0 && p.archive_index<=p.archives.length && Number.isInteger(p.object_index) && p.object_index>=0 && p.object_index<=16,'checkpoint_member_invalid');
    if(p.archive_index<p.archives.length) need(p.object_index<=p.archives[p.archive_index].objects.length,'checkpoint_member_invalid');
  }
  need(JSON.stringify(c).length<=40000,'checkpoint_too_large');
}
function expectedProperties(ctx) { const a=currentArchive(ctx),m=currentMember(ctx); return {drSchema:'drive-copy-v1',drKind:a.kind,drManifest:a.manifest_sha256,drObject:m.sha256}; }
function equalProperties(a,b) { return a && typeof a==='object' && Object.keys(a).length===Object.keys(b).length && Object.keys(b).every(k=>a[k]===b[k]); }
function driveFile(ctx, value) {
  const m=currentMember(ctx),r=ctx.reservation,d=ctx.destination;
  need(value && value.id===r.file_id && value.name===r.file_name && value.mimeType===m.mime_type && value.trashed===false && value.shared===false,'drive_file_identity_mismatch');
  need(Array.isArray(value.parents) && value.parents.length===1 && value.parents[0]===FOLDER,'drive_file_parent_mismatch');
  need(Array.isArray(value.owners) && value.owners.length===1 && value.owners[0].emailAddress===ACCOUNT && value.owners[0].permissionId===d.account_permission_id,'drive_file_owner_mismatch');
  need(Array.isArray(value.permissions) && value.permissions.length===1 && value.permissions[0].role==='owner' && value.permissions[0].type==='user' && value.permissions[0].emailAddress===ACCOUNT,'drive_file_permissions_mismatch');
  need(equalProperties(value.appProperties,r.app_properties) && /^\d+$/.test(String(value.size)),'drive_file_properties_mismatch');
  const size=Number(value.size); need(Number.isSafeInteger(size) && size>=0 && size<=MAX_OBJECT,'drive_file_size_invalid');
  if(size>0) need(size===m.size_bytes && (!value.sha256Checksum || value.sha256Checksum===m.sha256),'drive_nonempty_file_mismatch');
  return {id:value.id,name:value.name,parents:[FOLDER],owner_email:value.owners[0].emailAddress,
    owner_permission_id:value.owners[0].permissionId,shared:value.shared,trashed:value.trashed,
    mime_type:value.mimeType,size_bytes:size,app_properties:copy(value.appProperties)};
}
function responseBody(response) { need(response && Number.isInteger(response.statusCode) && response.statusCode>=200 && response.statusCode<300,'archive_http_failed'); return response.body; }
function clearMember(ctx) { delete ctx.reservation; delete ctx.proposed_file_id; delete ctx.drive_file; delete ctx.source_ready; delete ctx.have_download; delete ctx.uploaded; delete ctx.create_attempted; delete ctx.upload_url; delete ctx.completion; }

need($env.DROP_RATE_DRIVE_ARCHIVE_ENABLED==='true','drive_archive_disabled');
const execution_id=String($execution.id||'');
need(/^[A-Za-z0-9_.:-]{1,120}$/.test(execution_id),'execution_id_invalid');
const stored=$getWorkflowStaticData('global').dr95_checkpoint;
const checkpoint=stored ? copy(stored) : emptyCheckpoint();
validateCheckpoint(checkpoint);
return output({execution_id,started_at_ms:Date.now(),phase:'ADVANCE',checkpoint,
  counters:{pages:0,objects:0,bytes:0,archives:0,previously_recorded:0},destination:null,authorized_phase:null});

